import React, { useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Link } from 'react-router-dom';
import { Bike, Car, MapPinned, Phone, Plus, Search, Star, Truck, UserPlus } from 'lucide-react';
import { useAdmin } from '../lib/store';
import { Avatar, Badge, MapView, Modal, PageHeader, Progress, StatCard, cn } from '../lib/ui';
import { formatUZS, type Courier } from '../lib/mock';

const vehicleIcon = (v: Courier['vehicle']) => (v === 'Car' ? <Car size={13} /> : v === 'Bike' ? <Bike size={13} /> : <Truck size={13} />);

const emptyCourier = (): Courier => ({
  id: `c${Date.now()}`,
  name: '',
  phone: '',
  vehicle: 'Scooter',
  status: 'online',
  deliveries: 0,
  activeOrders: 0,
  rating: 4.5,
  x: 30 + Math.random() * 40,
  y: 30 + Math.random() * 40,
  emoji: '🛵',
});

export const Couriers = () => {
  const { t } = useTranslation();
  const { couriers, orders, assignCourier, saveCourier, notify } = useAdmin();
  const [query, setQuery] = useState('');
  const [filter, setFilter] = useState('all');
  const [addOpen, setAddOpen] = useState(false);
  const [draft, setDraft] = useState<Courier>(emptyCourier());
  const [assignTarget, setAssignTarget] = useState<Courier | null>(null);
  const [orderChoice, setOrderChoice] = useState('');

  const filtered = useMemo(() => {
    let list = [...couriers];
    const q = query.trim().toLowerCase();
    if (q) list = list.filter((c) => `${c.name} ${c.phone}`.toLowerCase().includes(q));
    if (filter !== 'all') list = list.filter((c) => c.status === filter);
    return list;
  }, [couriers, query, filter]);

  const online = couriers.filter((c) => c.status === 'online').length;
  const busy = couriers.filter((c) => c.status === 'busy').length;
  const deliveries = couriers.reduce((s, c) => s + c.deliveries, 0);
  const unassigned = orders.filter((o) => !o.courierId && o.status !== 'delivered' && o.status !== 'cancelled');

  const submit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!draft.name.trim() || !draft.phone.trim()) {
      notify('Ism va telefonni kiriting', 'error');
      return;
    }
    saveCourier({ ...draft, emoji: draft.vehicle === 'Car' ? '🚗' : draft.vehicle === 'Bike' ? '🚲' : '🛵' });
    notify(t('created'));
    setAddOpen(false);
    setDraft(emptyCourier());
  };

  const assign = () => {
    if (!assignTarget || !orderChoice) return;
    assignCourier(orderChoice, assignTarget.id);
    notify(`${t('assigned')}: #${orderChoice}`);
    setAssignTarget(null);
    setOrderChoice('');
  };

  return (
    <div className="animate-fade-up">
      <PageHeader
        title={t('couriersTitle')}
        subtitle={t('couriersSubtitle')}
        action={
          <>
            <Link to="/tracking" className="btn-secondary btn-sm hidden sm:inline-flex"><MapPinned size={15} /> {t('tracking')}</Link>
            <button className="btn-primary btn-sm" onClick={() => { setDraft(emptyCourier()); setAddOpen(true); }}>
              <Plus size={16} /> {t('addCourier')}
            </button>
          </>
        }
      />

      <div className="mb-5 grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4">
        <StatCard label="Jami kuryer" value={String(couriers.length)} icon={<Truck size={20} />} />
        <StatCard label={t('online')} value={String(online)} icon={<span className="h-3 w-3 rounded-full bg-brand-500" />} tone="sky" />
        <StatCard label={t('busy')} value={String(busy)} icon={<Truck size={20} />} tone="amber" />
        <StatCard label="Bugungi yetkazmalar" value={String(deliveries)} icon={<Star size={20} />} tone="violet" />
      </div>

      <div className="mb-5 grid grid-cols-1 gap-5 xl:grid-cols-3">
        <div className="card p-5 xl:col-span-2">
          <div className="mb-3 flex items-center justify-between">
            <div>
              <h2 className="font-display text-lg font-extrabold">{t('mapTitle')}</h2>
              <p className="mt-0.5 text-xs text-[var(--muted)]">{t('mapSub')}</p>
            </div>
            <span className="badge bg-brand-500/15 text-brand-700 dark:text-brand-300">
              <span className="h-1.5 w-1.5 animate-pulse rounded-full bg-brand-500" /> {t('live')}
            </span>
          </div>
          <MapView couriers={couriers} height={300} />
        </div>

        <div className="card p-5">
          <h2 className="font-display text-lg font-extrabold">Tayinlanmagan buyurtmalar</h2>
          <p className="mt-0.5 text-xs text-[var(--muted)]">Kuryer biriktirish kerak</p>
          <div className="mt-4 space-y-2">
            {unassigned.length === 0 && <p className="rounded-xl bg-[var(--surface-2)] p-3 text-center text-xs text-[var(--muted)]">Barcha buyurtmalar tayinlangan 🎉</p>}
            {unassigned.slice(0, 4).map((o) => (
              <div key={o.id} className="rounded-xl border p-2.5" style={{ borderColor: 'var(--border)' }}>
                <div className="flex items-center justify-between gap-2">
                  <p className="text-xs font-extrabold">#{o.id}</p>
                  <p className="text-[10px] font-bold text-[var(--muted)]">{formatUZS(o.total)}</p>
                </div>
                <p className="mt-0.5 truncate text-[10px] text-[var(--muted)]">{o.address}</p>
                <button
                  className="btn-primary btn-sm mt-2 w-full"
                  onClick={() => {
                    const free = couriers.find((c) => c.status === 'online') ?? couriers[0];
                    if (free) {
                      setAssignTarget(free);
                      setOrderChoice(o.id);
                    }
                  }}
                >
                  <UserPlus size={12} /> {t('assignCourier')}
                </button>
              </div>
            ))}
          </div>
        </div>
      </div>

      <div className="card p-4 sm:p-5">
        <div className="mb-4 flex flex-col gap-2 sm:flex-row">
          <div className="relative flex-1">
            <Search size={17} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-[var(--muted)]" />
            <input className="input pl-10" placeholder="Kuryer qidirish..." value={query} onChange={(e) => setQuery(e.target.value)} />
          </div>
          <select className="select sm:w-44" value={filter} onChange={(e) => setFilter(e.target.value)}>
            <option value="all">{t('all')}</option>
            <option value="online">{t('online')}</option>
            <option value="busy">{t('busy')}</option>
            <option value="offline">{t('offline')}</option>
          </select>
        </div>

        <div className="grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-3">
          {filtered.map((c) => (
            <div key={c.id} className="card group p-4 transition-all duration-300 hover:-translate-y-1">
              <div className="flex items-start gap-3">
                <Avatar emoji={c.emoji} size="lg" online={c.status !== 'offline'} />
                <div className="min-w-0 flex-1">
                  <p className="truncate text-sm font-extrabold">{c.name}</p>
                  <p className="mt-0.5 flex items-center gap-1 text-[10px] font-semibold text-[var(--muted)]">
                    {vehicleIcon(c.vehicle)} {c.vehicle} · ID {c.id.toUpperCase()}
                  </p>
                  <div className="mt-1.5 flex items-center gap-1">
                    <Star size={11} className="fill-amber-400 text-amber-400" />
                    <span className="text-[10px] font-extrabold">{c.rating}</span>
                    <span className="text-[10px] text-[var(--muted)]">· {c.deliveries} yetkazma</span>
                  </div>
                </div>
                <Badge tone={c.status === 'online' ? 'success' : c.status === 'busy' ? 'warning' : 'neutral'}>
                  {c.status === 'online' ? t('online') : c.status === 'busy' ? t('busy') : t('offline')}
                </Badge>
              </div>

              <div className="mt-3 grid grid-cols-2 gap-2">
                <div className="card-soft p-2 text-center">
                  <p className="font-display text-base font-extrabold">{c.activeOrders}</p>
                  <p className="text-[9px] font-bold text-[var(--muted)]">{t('activeOrders')}</p>
                </div>
                <div className="card-soft p-2 text-center">
                  <p className="font-display text-base font-extrabold">{c.deliveries}</p>
                  <p className="text-[9px] font-bold text-[var(--muted)]">{t('deliveries')}</p>
                </div>
              </div>

              <div className="mt-3">
                <div className="mb-1 flex justify-between text-[9px] font-bold text-[var(--muted)]">
                  <span>Samaradorlik</span><span>{Math.round((c.rating / 5) * 100)}%</span>
                </div>
                <Progress value={(c.rating / 5) * 100} tone={c.status === 'offline' ? 'rose' : 'brand'} />
              </div>

              <div className="mt-3 flex gap-1.5">
                <a href={`tel:${c.phone.replace(/\s/g, '')}`} className="icon-btn h-8 w-8"><Phone size={13} /></a>
                <button className="btn-primary btn-sm flex-1" onClick={() => { setAssignTarget(c); setOrderChoice(unassigned[0]?.id ?? ''); }}>
                  <UserPlus size={12} /> {t('assignOrder')}
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>

      <Modal open={addOpen} onClose={() => setAddOpen(false)} title={t('addCourier')} subtitle="Yangi kuryer ma'lumotlari">
        <form onSubmit={submit} className="space-y-4">
          <div>
            <label className="label">{t('name')}</label>
            <input className="input" value={draft.name} onChange={(e) => setDraft({ ...draft, name: e.target.value })} placeholder="Ism familiya" />
          </div>
          <div>
            <label className="label">{t('phone')}</label>
            <input className="input" value={draft.phone} onChange={(e) => setDraft({ ...draft, phone: e.target.value })} placeholder="+998 90 123 45 67" />
          </div>
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="label">{t('vehicle')}</label>
              <select className="select" value={draft.vehicle} onChange={(e) => setDraft({ ...draft, vehicle: e.target.value as Courier['vehicle'] })}>
                <option value="Scooter">Scooter 🛵</option>
                <option value="Bike">Bike 🚲</option>
                <option value="Car">Car 🚗</option>
              </select>
            </div>
            <div>
              <label className="label">{t('status')}</label>
              <select className="select" value={draft.status} onChange={(e) => setDraft({ ...draft, status: e.target.value as Courier['status'] })}>
                <option value="online">{t('online')}</option>
                <option value="offline">{t('offline')}</option>
              </select>
            </div>
          </div>
          <div className="flex gap-2">
            <button type="button" className="btn-secondary flex-1" onClick={() => setAddOpen(false)}>{t('cancel')}</button>
            <button type="submit" className="btn-primary flex-1">{t('save')}</button>
          </div>
        </form>
      </Modal>

      <Modal
        open={!!assignTarget}
        onClose={() => setAssignTarget(null)}
        title={t('assignOrder')}
        subtitle={assignTarget ? `${assignTarget.emoji} ${assignTarget.name}` : ''}
      >
        <div className="space-y-4">
          {unassigned.length === 0 ? (
            <p className="rounded-xl bg-[var(--surface-2)] p-4 text-center text-sm text-[var(--muted)]">Tayinlanmagan buyurtma yo'q</p>
          ) : (
            <>
              <div>
                <label className="label">{t('order')}</label>
                <select className="select" value={orderChoice} onChange={(e) => setOrderChoice(e.target.value)}>
                  <option value="">Buyurtmani tanlang</option>
                  {unassigned.map((o) => (
                    <option key={o.id} value={o.id}>#{o.id} · {o.customer} · {formatUZS(o.total)}</option>
                  ))}
                </select>
              </div>
              <div className="flex gap-2">
                <button className="btn-secondary flex-1" onClick={() => setAssignTarget(null)}>{t('cancel')}</button>
                <button className="btn-primary flex-1" onClick={assign} disabled={!orderChoice}>{t('assignCourier')}</button>
              </div>
            </>
          )}
        </div>
      </Modal>
    </div>
  );
};
